export default async function init({ baseUrl, apiKey }, ctx) {
  if (!/^https:\/\//.test(baseUrl) || !apiKey) throw Error("Configure HTTPS n8n URL and API key");
  const p = await ctx.state.get("drive-workflow-backup-pending");
  if (p) throw Error("Inspect unresolved write: " + p.label);
  let cursor = null,
    workflows = [];
  do {
    const u = new URL(baseUrl.replace(/\/$/, "") + "/api/v1/workflows");
    u.searchParams.set("limit", "100");
    if (cursor) u.searchParams.set("cursor", cursor);
    const r = await ctx.fetch(u.toString(), { headers: { "X-N8N-API-KEY": apiKey } });
    if (!r.ok) throw Error("n8n workflow list failed");
    const b = await r.json();
    if (!Array.isArray(b.data)) throw Error("Invalid workflow list");
    workflows.push(...b.data);
    cursor = b.nextCursor ?? null;
  } while (cursor);
  await ctx.state.set("drive-workflow-run", {
    phase: "root",
    token: null,
    folders: [],
    files: [],
    workflows,
    index: 0,
    moved: 0,
    created: 0,
  });
  return { started: true };
}

