export default async function next(_input, ctx) {
  const s = await ctx.state.get("drive-workflow-run");
  if (!s) throw Error("Missing run state");
  let action = "done",
    q = null,
    pageToken = null,
    name = null,
    mimeType = null,
    parents = null,
    text = null,
    fileId = null,
    addParents = null,
    removeParents = null;
  for (;;) {
    if (s.phase === "root") {
      action = "list";
      q =
        "'root' in parents and trashed = false and mimeType = 'application/vnd.google-apps.folder' and (name = 'n8n_backups' or name = 'n8n_old')";
      pageToken = s.token;
      break;
    }
    if (s.phase === "folders") {
      for (const n of ["n8n_backups", "n8n_old"])
        if (s.folders.filter((x) => x.name === n).length > 1)
          throw Error("Multiple root folders named " + n);
      const missing = ["n8n_backups", "n8n_old"].find((n) => !s.folders.some((x) => x.name === n));
      if (missing) {
        action = "create";
        name = missing;
        mimeType = "application/vnd.google-apps.folder";
        parents = ["root"];
        await ctx.state.set("drive-workflow-backup-pending", { label: "create folder " + missing });
        break;
      }
      s.currentId = s.folders.find((x) => x.name === "n8n_backups").id;
      s.oldId = s.folders.find((x) => x.name === "n8n_old").id;
      s.phase = "files";
      s.token = null;
      await ctx.state.set("drive-workflow-run", s);
      continue;
    }
    if (s.phase === "files") {
      action = "list";
      q = "'" + s.currentId.replace(/'/g, "\\'") + "' in parents and trashed = false";
      pageToken = s.token;
      break;
    }
    if (s.phase === "move") {
      if (s.index >= s.files.length) {
        s.phase = "upload";
        s.index = 0;
        await ctx.state.set("drive-workflow-run", s);
        continue;
      }
      const f = s.files[s.index];
      if (!f.id) throw Error("Backup file missing ID");
      action = "update";
      fileId = f.id;
      addParents = s.oldId;
      removeParents = s.currentId;
      await ctx.state.set("drive-workflow-backup-pending", { label: "move " + f.id });
      break;
    }
    if (s.phase === "upload") {
      if (s.index >= s.workflows.length) {
        s.phase = "done";
        await ctx.state.set("drive-workflow-run", s);
        continue;
      }
      const w = s.workflows[s.index];
      if (!w.id || !w.name) throw Error("Invalid n8n workflow");
      action = "create";
      name =
        String(w.name) +
        "-" +
        (w.active ? "active" : "inactive") +
        "-" +
        (w.updatedAt ?? "unknown") +
        ".json";
      mimeType = "application/json";
      parents = [s.currentId];
      text = JSON.stringify(w, null, 2);
      await ctx.state.set("drive-workflow-backup-pending", { label: "upload workflow " + w.id });
      break;
    }
    if (s.phase === "done") break;
    throw Error("Invalid backup phase");
  }
  return {
    action,
    q,
    pageToken,
    name,
    mimeType,
    parents,
    text,
    fileId,
    addParents,
    removeParents,
    moved: s.moved,
    created: s.created,
  };
}

