export default async function accept({ files, nextPageToken }, ctx) {
  const s = await ctx.state.get("drive-workflow-run");
  if (!s || !["root", "files"].includes(s.phase) || !Array.isArray(files))
    throw Error("Invalid Drive list");
  if (s.phase === "root") s.folders.push(...files);
  else s.files.push(...files.filter((x) => x.name?.endsWith(".json")));
  s.token = nextPageToken ?? null;
  if (!s.token) {
    s.phase = s.phase === "root" ? "folders" : "move";
    s.index = 0;
  }
  await ctx.state.set("drive-workflow-run", s);
  return { ok: true };
}

