export default async function accept({ id, name }, ctx) {
  const s = await ctx.state.get("drive-workflow-run");
  if (!s || !id) throw Error("Create not confirmed");
  if (s.phase === "folders") {
    if (!["n8n_backups", "n8n_old"].includes(name)) throw Error("Unexpected folder");
    s.folders.push({ id, name });
  } else if (s.phase === "upload") {
    s.index++;
    s.created++;
  } else throw Error("Unexpected create phase");
  await ctx.state.set("drive-workflow-run", s);
  await ctx.state.set("drive-workflow-backup-pending", null);
  return { ok: true };
}

