export default async function accept({ id }, ctx) {
  const s = await ctx.state.get("drive-workflow-run");
  if (!s || s.phase !== "move" || id !== s.files[s.index]?.id) throw Error("Move not confirmed");
  s.index++;
  s.moved++;
  await ctx.state.set("drive-workflow-run", s);
  await ctx.state.set("drive-workflow-backup-pending", null);
  return { ok: true };
}
